mapper.select:
select t.checkin_time,t.checkin_time checkinTime,t.checkin_id,t.checkin_id
checkinId,t.machine_code,t.machine_code machineCode,t.open_type_cd,t.open_type_cd
openTypeCd,t.status_cd,t.status_cd statusCd,t.remark,t.machine_id,t.machine_id
machineId,t.staff_name,t.staff_name staffName,t.tel,t.face_path,t.face_path
facePath,t.state,t.community_id,t.community_id communityId,t.staff_id,t.staff_id staffId,
t.create_time createTime,am.machine_name machineName,am.machine_code machineCode
from attendance_checkin t
left join attendance_machine am on t.machine_id = am.machine_id and am.status_cd = '0'
where 1 =1

    and t.checkin_time= #{checkinTime}


    and t.checkin_id= #{checkinId}


    and t.machine_code= #{machineCode}


    and t.open_type_cd= #{openTypeCd}


    and t.status_cd= #{statusCd}


    and t.remark= #{remark}


    and t.machine_id= #{machineId}


    and t.staff_name= #{staffName}


    and t.tel= #{tel}


    and t.face_path= #{facePath}


    and t.state= #{state}


    and t.community_id= #{communityId}


    and t.staff_id= #{staffId}

order by t.create_time desc

    limit #{page}, #{row}

